304|async function readStream(resp, onEvent) {
305|  const reader = resp.body.getReader();
306|  const dec = new TextDecoder();
307|  let tail = "";
308|  for (;;) {
309|    const part = await reader.read();
310|    if (part.done) break;
311|    tail += dec.decode(part.value, { stream: true });
312|    const cut = tail.split("\n\n");
313|    tail = cut.pop();
314|    for (const raw of cut) {
315|      const lines = raw.split("\n");
316|      for (const ln of lines) {
317|        const t = ln.trim();
